def place(x, y):
    if x == 0 and y == 0:
        return "at the origin"
    elif x == 0:
        return "on the y-axis"
    elif y == 0:
        return "on the x-axis"
    elif x > 0 and y > 0:
        return "in quadrant I"
    elif x < 0 and y > 0:
        return "in quadrant II"
    elif x < 0:
        return "in quadrant III"
    else:
        return "in quadrant IV"

def direction(n, plus, minus):
    if n > 0:
        return f"{n} {plus}"
    elif n < 0:
        return f"{-n} {minus}"
    return f"0 {plus}"

cases = [
    ("quadrant I", 3, 2),
    ("quadrant II", -4, 1),
    ("quadrant III", -2, -3),
    ("quadrant IV", 4, -1),
    ("on an axis", 0, -3),
    ("the origin", 0, 0),
]
for label, x, y in cases:
    print(f"{label}: ({x}, {y}) is {direction(x, 'right', 'left')}, then {direction(y, 'up', 'down')}: {place(x, y)}")
    print(f"  mirrors: ({x}, {-y}) {place(x, -y)}, ({-x}, {y}) {place(-x, y)}, ({-x}, {-y}) {place(-x, -y)}")

